package org.slavicmyths.bogatyr;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.monster.*;
import net.minecraft.world.damagesource.DamageTypes;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.entity.EntityJoinLevelEvent;
import net.neoforged.neoforge.event.entity.living.*;

@EventBusSubscriber(modid="slavicmyths")
public final class BogatyrEvents {
    @SubscribeEvent public static void incoming(LivingIncomingDamageEvent e){if(!(e.getEntity() instanceof ServerPlayer p)||e.getAmount()<=0)return;if(e.getSource().getEntity() instanceof IdolishcheEntity)p.getPersistentData().putFloat("IdolHpBefore",p.getHealth());var h=BogatyrLedger.hero(p);if(h!=null&&h.canIntercept(p,e.getSource())){h.interceptUsed=true;float amount=e.getAmount();e.setCanceled(true);h.hurt(e.getSource(),amount);}}
    @SubscribeEvent public static void pre(LivingDamageEvent.Pre e){if(e.getEntity().level().isClientSide)return;if(e.getEntity() instanceof IlyaEntity h)e.setNewDamage(e.getNewDamage()*h.mitigation(e.getSource(),e.getNewDamage()));if(e.getSource().is(DamageTypes.FALL)){var n=e.getEntity().getPersistentData();if(n.getLong("IdolThrowUntil")>e.getEntity().level().getGameTime()){e.setNewDamage(Math.min(4,e.getNewDamage()));n.remove("IdolThrowUntil");}}
        if(e.getEntity() instanceof IdolishcheEntity b&&e.getSource().getEntity() instanceof ServerPlayer p){var n=p.getPersistentData();if(n.hasUUID("IdolComboBoss")&&n.getUUID("IdolComboBoss").equals(b.getUUID())&&n.getLong("IdolComboUntil")>=b.level().getGameTime()){e.setNewDamage(e.getNewDamage()*1.2F);n.remove("IdolComboBoss");n.remove("IdolComboUntil");}}}
    @SubscribeEvent public static void post(LivingDamageEvent.Post e){if(e.getSource().getEntity() instanceof IdolishcheEntity source)source.outgoingHit(e.getEntity(),e.getNewDamage());if(e.getEntity() instanceof IdolishcheEntity b)b.registeredHit(e.getSource(),e.getOriginalDamage(),e.getNewDamage());if(e.getSource().getEntity() instanceof IdolishcheEntity b&&e.getEntity() instanceof ServerPlayer p){b.contribution(p);b.lastDamageReport=String.format(java.util.Locale.ROOT,"[Boss171] target=%s hit=%s armor=%d toughness=%.1f hpBefore=%.3f hpAfter=%.3f preArmorDamage=%.3f postArmorDamage=%.3f postEffectsDamage=%.3f affectedByShield=%s statusEffects=%s",p.getUUID(),e.getSource().getMsgId(),p.getArmorValue(),p.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.ARMOR_TOUGHNESS),p.getPersistentData().getFloat("IdolHpBefore"),p.getHealth(),e.getOriginalDamage(),e.getOriginalDamage()-e.getReduction(net.neoforged.neoforge.common.damagesource.DamageContainer.Reduction.ARMOR),e.getNewDamage(),p.isBlocking(),p.getActiveEffects());org.slf4j.LoggerFactory.getLogger("Boss171").info(b.lastDamageReport);}if(e.getEntity() instanceof IlyaEntity h&&h.ready("pain")&&e.getNewDamage()>0){h.cooldown("pain",16);h.cue(h.getRandom().nextBoolean()?"pain_nonverbal_01":"pain_nonverbal_02");}}
    @SubscribeEvent public static void join(EntityJoinLevelEvent e){if(!(e.getLevel() instanceof ServerLevel w))return;if(e.getEntity() instanceof Zombie z&&z.getPersistentData().hasUUID("IdolOwner")){var owner=w.getEntity(z.getPersistentData().getUUID("IdolOwner"));if(!(owner instanceof IdolishcheEntity b)||!b.active||!b.encounter.equals(z.getPersistentData().getUUID("IdolEncounter"))){z.discard();e.setCanceled(true);}else z.goalSelector.addGoal(0,new IdolMinionGoal(z));}
        if(e.getEntity() instanceof Monster m){m.targetSelector.addGoal(0,new net.minecraft.world.entity.ai.goal.Goal(){{setFlags(java.util.EnumSet.of(Flag.TARGET));}public boolean canUse(){return target()!=null;}public boolean canContinueToUse(){return target()!=null;}private IlyaEntity target(){var n=m.getPersistentData();return n.getLong("BogatyrTauntUntil")>w.getGameTime()&&n.hasUUID("BogatyrTauntHero")&&w.getEntity(n.getUUID("BogatyrTauntHero")) instanceof IlyaEntity h&&h.isAlive()&&!h.recovering()&&m.hasLineOfSight(h)?h:null;}public void start(){setFlags(java.util.EnumSet.of(Flag.TARGET));m.setTarget(target());}public void tick(){m.setTarget(target());}public void stop(){if(m.getTarget() instanceof IlyaEntity)m.setTarget(null);}});}}
    private BogatyrEvents(){}
    @SubscribeEvent public static void landing(LivingFallEvent e){if(!(e.getEntity().level() instanceof ServerLevel w))return;var n=e.getEntity().getPersistentData();if(n.getLong("IdolThrowUntil")<w.getGameTime()||!n.hasUUID("IdolThrowBoss"))return;var id=n.getUUID("IdolThrowBoss");n.remove("IdolThrowUntil");n.remove("IdolThrowBoss");e.setDamageMultiplier(0);if(w.getEntity(id) instanceof IdolishcheEntity b)e.getEntity().hurt(IdolishcheEntity.source(b,"grasp"),10);}
}
